(function (payload) {
	const LOGGER = new sn_aia.AIAgentsLogger("Now LLM Large Unified Planner Response Validator");
	const TICKS = '```';
	const TICKS_JSON = '```json';
	try {
		var response = JSON.parse(payload.response[0]).model_output;

		//Very rarely, NowLLM will send out json``` at the beginning of the response
		//and another ``` at the end of the response. We'll parse it out here
		var indexTickJson = response.indexOf(TICKS_JSON);
		var indexTickStart = response.indexOf(TICKS);
		var indexTickEnd = response.lastIndexOf(TICKS);
		if (indexTickStart != -1 && indexTickEnd != -1) {
			var tickStartLength = (indexTickJson != -1) ? TICKS_JSON.length : TICKS.length;
			response = response.substring(indexTickStart + tickStartLength, indexTickEnd);
		}
		payload.response[0] = response;
	} catch (e) {
		LOGGER.error("Error in Unified Planner Response validator: {0}", [e.toString()]);
		payload.response[0] = JSON.stringify({});
	}
	return payload;
})(payload);

(function (payload) {
    const LOGGER = new sn_aia.AIAgentsLogger("3P LLM Unified Planner Response Validator");
    var outputs = payload;
    var unified_planner_util = new sn_aia.AgentUnifiedPlannerUtil();

    try {
        var response = outputs['response'][0];

        var extractedJson = unified_planner_util.parseAllJsonFormats(response);
        if (extractedJson) {
            response = extractedJson;
        } else {
            LOGGER.info("No valid JSON found in response, keeping original response");
        }

        payload.response[0] = response;
    } catch (e) {
        LOGGER.error("Error in Unified Planner Response validator: {0}", [e.toString()]);
        payload.response[0] = JSON.stringify({});
    }
    return payload;
})(payload);
